import { Component } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../core/services/auth.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.scss']
})
export class LoginComponent {
  form = this.fb.group({
    email:    ['', [Validators.required, Validators.email]],
    password: ['', Validators.required]
  });

  loading = false;
  error   = '';

  constructor(private fb: FormBuilder, private auth: AuthService, private router: Router) {}

  submit(): void {
    if (this.form.invalid || this.loading) return;
    this.loading = true;
    this.error   = '';

    this.auth.login(this.form.value as any).subscribe({
      next:  () => this.router.navigate(['/']),
      error: (err) => {
        this.error   = err.error?.error ?? 'Error al iniciar sesión.';
        this.loading = false;
      }
    });
  }
}
<div class="auth-page">
  <div class="auth-card card">
    <div class="auth-logo">🤝</div>
    <h2>Inicia sesión</h2>
    <p class="auth-sub">Bienvenido de vuelta</p>

    <div class="alert alert-error" *ngIf="error">{{ error }}</div>

    <form [formGroup]="form" (ngSubmit)="submit()">
      <div class="form-group">
        <label>Email</label>
        <input type="email" formControlName="email" placeholder="tu@email.com">
        <span class="error-msg"
          *ngIf="form.controls['email'].invalid && form.controls['email'].touched">
          Email inválido.
        </span>
      </div>

      <div class="form-group">
        <label>Contraseña</label>
        <input type="password" formControlName="password" placeholder="••••••••">
      </div>

      <button type="submit" class="btn btn-primary full" [disabled]="loading">
        {{ loading ? 'Ingresando...' : 'Ingresar' }}
      </button>
    </form>

    <p class="auth-link">
      ¿No tienes cuenta? <a routerLink="/register">Regístrate gratis</a>
    </p>
  </div>
</div>
